"""Feed completeness report - translated from null_handling_report.pl.

Splits each pipe-delimited record and scores populated fields against the
number of fields the record carried.
"""
from __future__ import annotations

from typing import Dict

import pandas as pd


def run(inputs: Dict[str, str]) -> pd.DataFrame:
    rows = []

    with open(inputs["raw_feed"], "r", encoding="utf-8") as fh:
        fh.readline()                                  # header
        for line in fh:
            line = line.rstrip("\n").rstrip("\r")
            if not line:
                continue

            fields = line.split("|")

            field_count = len(fields)
            if not field_count:
                continue

            populated = sum(1 for v in fields if v is not None and len(v))
            rows.append({
                "record_id": fields[0],
                "field_count": field_count,
                "populated_fields": populated,
                "completeness_pct": "%.1f" % (100 * populated / field_count),
            })

    return pd.DataFrame(rows, columns=["record_id", "field_count",
                                       "populated_fields", "completeness_pct"])
